Method.Implementation:
	set pResponse=##class(IHC.ITF.ITFCOMMON.DataStructure.ChargeSuperset).%New()

	set dbObj = ##class(IHC.ITF.ITFCOMMON.TouchWorksStoredProcUtil).%New(..Adapter)

	Set tSC = dbObj.GetExtractEncounterCMS(req, .resp)
	if $$$ISERR(tSC)
  	{
	  	return tSC
  	}
  	set pResponse.ExtractEncounterCMS = resp
  	Set tSC = dbObj.GetExtractPatientCMS(req, .resp)
	if $$$ISERR(tSC)
  	{
	  	return tSC
  	}
	set pResponse.ExtractPatientCMS = resp

  	Set tSC = dbObj.GetExtractPersonCMS(req, .resp)
	if $$$ISERR(tSC)
  	{
	  	return tSC
  	}
	set pResponse.ExtractPersonCMS = resp

  	Set tSC = dbObj.ExtractChargeCMS(req, .resp)
	if $$$ISERR(tSC)
  	{
	  	return tSC
  	}
	set pResponse.ExtractChargeCMS = resp

	Set tSC = dbObj.ExtractVisitCMS(req, .resp)
	if $$$ISERR(tSC)
  	{
	  	return tSC
  	}
	set pResponse.ExtractVisitCMS = resp

  	Set tSC = dbObj.ExtractChargeAdditionalInfo(req, .resp)
	if $$$ISERR(tSC)
  	{
	  	return tSC
  	}
	set pResponse.ExtractChargeAdditionalInfo = resp

  	Set tSC = dbObj.GetExtractInsuranceCMS(req, .resp)
	if $$$ISERR(tSC)
  	{
	  	return tSC
  	}
	set pResponse.ExtractInsurance = resp

  	Set tSC = dbObj.GetExtractCase(req, .resp)
	if $$$ISERR(tSC)
  	{
	  	return tSC
  	}
	set pResponse.ExtractCase = resp
  	Set tSC = dbObj.FlowcastChargeDBLookup(pResponse.ExtractEncounterCMS.ExtractEncounterCMSVisitID, pResponse.ExtractChargeCMS.ExtractChargeCMSBillingProviderID, pResponse.ExtractChargeCMS.ExtractChargeCMSBillingReferProviderID, pResponse)


  	return tSC
